eval <t> (async () => {
  await new Promise(r => setTimeout(r, 1200));
  const hash = (s) => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
    return h.toString(16).padStart(8, '0');
  };
  const KEY = ['color','background-color','background-image','border-top-color','border-top-width','border-top-style','border-radius','box-shadow','outline-color','opacity','filter','font-family','font-size','font-weight','padding-top','padding-left','margin-top','width','height','fill','stroke','display','visibility'];
  const pathOf = (el, root) => {
    const parts = [];
    let e = el;
    while (e && e !== root) {
      const idx = Array.prototype.indexOf.call(e.parentElement.children, e) + 1;
      parts.unshift(e.tagName.toLowerCase() + ':' + idx);
      e = e.parentElement;
    }
    return parts.join('>') || '(root)';
  };
  const styleOf = (el, pseudo) => {
    const cs = getComputedStyle(el, pseudo);
    let s = '';
    for (let i = 0; i < cs.length; i++) { const p = cs[i]; s += p + '=' + cs.getPropertyValue(p) + ';'; }
    return s;
  };
  const keyOf = (el, pseudo) => {
    const cs = getComputedStyle(el, pseudo);
    const o = {};
    for (const p of KEY) o[p] = cs.getPropertyValue(p);
    return o;
  };
  const attrsOf = (el) => Array.from(el.attributes).map(a => a.name + '=' + a.value).join(' ');
  const out = {
    doc: {
      dataTheme: document.documentElement.getAttribute('data-theme'),
      htmlClass: document.documentElement.className,
      bodyClass: document.body.className,
      bodyBg: getComputedStyle(document.body).backgroundColor
    },
    widgets: {}
  };
  for (const id of ['w-revenue', 'w-users', 'w-churn', 'w-tickets']) {
    const root = document.getElementById(id);
    if (!root) { out.widgets[id] = 'MISSING'; continue; }
    const els = [root, ...root.querySelectorAll('*')];
    const recs = [];
    for (const el of els) {
      const p = pathOf(el, root);
      recs.push({ p, a: hash(attrsOf(el)), c: hash(styleOf(el)), k: keyOf(el) });
      for (const ps of ['::before', '::after']) {
        const cs = getComputedStyle(el, ps);
        if (cs.content !== 'none' && cs.content !== 'normal') {
          recs.push({ p: p + ps, c: hash(styleOf(el, ps)), k: keyOf(el, ps) });
        }
      }
    }
    out.widgets[id] = { text: hash(root.innerText), html: hash(root.innerHTML), n: els.length, els: recs };
  }
  return JSON.stringify(out);
})()

